// Web Worker entry: same-origin `/api/*` goes to the API Worker (Python, D1)
// over the API service binding; everything else is the Next.js app (OpenNext).
// The request is forwarded as-is, so the Cloudflare Access JWT header/cookie
// reaches the API, which verifies it.

// Generated by `opennextjs-cloudflare build`: absent before a build (type error)
// and present after (no error), so @ts-expect-error can't be used.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";

// Minimal binding types, so the Next app's DOM typings stay untouched.
type Env = { API: { fetch(request: Request): Promise<Response> } };

const worker = {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const { pathname } = new URL(request.url);
    if (pathname === "/api" || pathname.startsWith("/api/")) {
      return env.API.fetch(request);
    }
    return handler.fetch(request, env, ctx);
  },
};

export default worker;
